def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fits = bins >= item
    target_deviation = np.abs(0.5 * bins - item)
    return np.where(fits, -target_deviation, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    fit_mask = bins >= item
    return np.where(fit_mask, np.floor(bins / item), -np.inf)

